    "H": { "1": {"name": "Phrases 1 (動名詞)", "focus": "學習動名詞(V-ing)當主詞、受詞與補語的用法。"}, "11": {"name": "Phrases 2 (具有名詞作用的不定詞)", "focus": "學習不定詞(to + V)當名詞用法的結構。"}, "21": {"name": "Phrases 3 (具有形容詞作用的不定詞)", "focus": "學習不定詞修飾名詞的形容詞用法。"}, "31": {"name": "Phrases 4 (具有副詞作用的不定詞)", "focus": "學習不定詞表目的/原因的副詞用法。"}, "41": {"name": "Story 1: Gulliver's Travels", "focus": "長篇文學名著閱讀與句型分析。"}, "51": {"name": "Phrases 5 (tell/ask＋受詞＋不定詞，wh-疑問詞＋不定詞)", "focus": "掌握tell/ask + O + to V及疑問詞+to V結構。"}, "61": {"name": "Phrases 6 (too...to-，enough to-，It is...to-)", "focus": "掌握too...to..., enough to..., 虛主詞It...to V句型。"}, "71": {"name": "Voice 1 (被動語態：基本結構)", "focus": "掌握被動語態(be + p.p.)基本結構。"}, "81": {"name": "Voice 2 (被動語態：主詞＋動詞＋受詞＋受詞型式的句子、否定和疑問句)", "focus": "掌握雙受詞被動語態與被動否定/疑問句。"}, "91": {"name": "Story 2: Thomas Edison", "focus": "傳記閱讀與被動語態應用。"}, "101": {"name": "Voice 3 (have＋受詞過去分詞，帶有助動詞的被動句)", "focus": "掌握助動詞被動句與have + O + p.p.結構。"}, "111": {"name": "Voice 4 (修飾名詞的過去分詞和現在分詞)", "focus": "掌握分詞(V-ing / p.p.)當形容詞修飾名詞。"}, "121": {"name": "Tense 1 (Will和be going to表示未來式)", "focus": "掌握Will與be going to未來式差異與用法。"}, "131": {"name": "Tense 2 (現在完成式：已經完成的動作、否定句、疑問句)", "focus": "掌握現在完成式(have/has + p.p.)完成用法。"}, "141": {"name": "Story 3: Jack and the Beanstalk", "focus": "童話故事閱讀與完成式應用。"}, "151": {"name": "Tense 3 (現在完成式)", "focus": "掌握現在完成式經驗與持續用法(for / since)。"}, "161": {"name": "Tense 4 (現在完成式 現在完成進行式)", "focus": "掌握現在完成進行式(have/has been + V-ing)。"}, "171": {"name": "Tense 5 (現在完成式+各種疑問句)", "focus": "掌握完成式特殊疑問句與How long...句型。"}, "181": {"name": "Tense 6 (過去完成式、未來完成式)", "focus": "掌握過去完成式(had + p.p.)與未來完成式。"}, "191": {"name": "Story 4: Peter Pan", "focus": "名著閱讀與時態綜合演練。"} },
